import{_ as a,o as l,c as r,a8 as o}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"2.x.x","description":"","frontmatter":{"title":"2.x.x","lang":"zh-CN"},"headers":[],"relativePath":"zh-cn/changes/2_x_x.md","filePath":"zh-cn/changes/2_x_x.md","lastUpdated":1790354326000}'),i={name:"zh-cn/changes/2_x_x.md"};function t(c,e,d,f,h,n){return l(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIyLngueCUyMiUyQyUyMmxhbmclMjIlM0ElMjJ6aC1DTiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzU0MzI2MDAwJTdE"},[...e[0]||(e[0]=[o(`<h1 id="更新日志-2-x-x" tabindex="-1">更新日志（2.x.x） <a class="header-anchor" href="#更新日志-2-x-x" aria-label="Permalink to &quot;更新日志（2.x.x）&quot;">​</a></h1><p>本文件的格式基于<a href="https://keepachangelog.com/zh-CN/1.0.0" target="_blank" rel="noreferrer">如何维护更新日志</a>， 并且本项目遵守<a href="https://semver.org/lang/zh-CN/spec/v2.0.0.html" target="_blank" rel="noreferrer">语义化版本</a>。</p><div class="tip custom-block"><p class="custom-block-title">何为「不兼容的修改」？</p><ul><li>原有的配置文件可能无法使用，比如删除或者重命名了某个配置项。</li><li>可能需要更新编译环境，比如安装新的依赖。</li></ul></div><h2 id="_2-1-1-2020-12-10" tabindex="-1">[2.1.1] - 2020-12-10 <a class="header-anchor" href="#_2-1-1-2020-12-10" aria-label="Permalink to &quot;[2.1.1] - 2020-12-10&quot;">​</a></h2><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><h3 id="改动" tabindex="-1">改动 <a class="header-anchor" href="#改动" aria-label="Permalink to &quot;改动&quot;">​</a></h3><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复了模块启动失败的 bug。此 bug 的报错信息为 <code>nginx: [alert] could not open error log file: open() &quot;ngx_waf: /logs/error.log&quot; failed (2: No such file or directory)</code>（<a href="https://github.com/ADD-SP/ngx_waf/commit/0dfc46f2dfc7ed91977b501c868abf961966d4e1" target="_blank" rel="noreferrer">0dfc46f</a>）。</li></ul><hr><h2 id="_2-1-0-2020-12-09" tabindex="-1">[2.1.0] - 2020-12-09 <a class="header-anchor" href="#_2-1-0-2020-12-09" aria-label="Permalink to &quot;[2.1.0] - 2020-12-09&quot;">​</a></h2><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>兼容了 Mainline 版本的 nginx（<a href="https://github.com/ADD-SP/ngx_waf/commit/f31f906b11fb00f54bfea504ca7c8c147a0be1d8" target="_blank" rel="noreferrer">f31f906</a> &amp; <a href="https://github.com/ADD-SP/ngx_waf/commit/7b4f897a4a332b43bf94de874f8ba8c3098aaee4" target="_blank" rel="noreferrer">65277d1</a>）。</li></ul><h3 id="改动-1" tabindex="-1">改动 <a class="header-anchor" href="#改动-1" aria-label="Permalink to &quot;改动&quot;">​</a></h3><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><h2 id="_2-0-2-2020-12-07" tabindex="-1">[2.0.2] - 2020-12-07 <a class="header-anchor" href="#_2-0-2-2020-12-07" aria-label="Permalink to &quot;[2.0.2] - 2020-12-07&quot;">​</a></h2><h3 id="新增-2" tabindex="-1">新增 <a class="header-anchor" href="#新增-2" aria-label="Permalink to &quot;新增&quot;">​</a></h3><h3 id="改动-2" tabindex="-1">改动 <a class="header-anchor" href="#改动-2" aria-label="Permalink to &quot;改动&quot;">​</a></h3><h3 id="修复-2" tabindex="-1">修复 <a class="header-anchor" href="#修复-2" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>修复了一个 CC 防御失效的 bug。此 bug 会导致当 <code>waf_mult_mount</code> 未启用时，CC 防御会失效（<a href="https://github.com/ADD-SP/ngx_waf/commit/048fe5c15863d9a3106387225774305aa5564726" target="_blank" rel="noreferrer">048fe5c</a>）。</p></li><li><p>修复了一个因错误的 <code>#include</code> 指令而导致编译失败的 bug（<a href="https://github.com/ADD-SP/ngx_waf/commit/3fa298c6184618ea0cd6336783a4d7a2ed27469c" target="_blank" rel="noreferrer">3fa298c</a>）。</p></li></ul><hr><h2 id="_2-0-1-2020-12-03" tabindex="-1">[2.0.1] - 2020-12-03 <a class="header-anchor" href="#_2-0-1-2020-12-03" aria-label="Permalink to &quot;[2.0.1] - 2020-12-03&quot;">​</a></h2><h3 id="新增-3" tabindex="-1">新增 <a class="header-anchor" href="#新增-3" aria-label="Permalink to &quot;新增&quot;">​</a></h3><h3 id="改动-3" tabindex="-1">改动 <a class="header-anchor" href="#改动-3" aria-label="Permalink to &quot;改动&quot;">​</a></h3><ul><li>不再手动下载 uthash 依赖，改用 system library。可以使用 <code>yum install uthash-devel</code> 或 <code>apt-get install uthash-dev</code> 安装 system library（<a href="https://github.com/ADD-SP/ngx_waf/commit/7cfc94bc64fa4f2c29bdf3b24e21aeb1ba412054" target="_blank" rel="noreferrer">7cfc94b</a>）。</li></ul><h3 id="修复-3" tabindex="-1">修复 <a class="header-anchor" href="#修复-3" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复了因为宏的重定义导致的在 CentOS/RHEL 6 or 7 下编译失败的错误（<a href="https://github.com/ADD-SP/ngx_waf/commit/28e1c8aca03375089c75df21c5db3c38013edde7" target="_blank" rel="noreferrer">28e1c8a</a> &amp; <a href="https://github.com/ADD-SP/ngx_waf/commit/566ae4a50f855674b256db84305a24e1b2a6bc6d" target="_blank" rel="noreferrer">566ae4a</a>）。</li></ul><hr><h2 id="_2-0-0-2020-09-29" tabindex="-1">[2.0.0] - 2020-09-29 <a class="header-anchor" href="#_2-0-0-2020-09-29" aria-label="Permalink to &quot;[2.0.0] - 2020-09-29&quot;">​</a></h2><h3 id="新增-4" tabindex="-1">新增 <a class="header-anchor" href="#新增-4" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>支持以动态模块安装到 nginx 上，感谢 <a href="https://github.com/dvershinin" target="_blank" rel="noreferrer">dvershinin</a>的 PR（<a href="https://github.com/ADD-SP/ngx_waf/pull/4%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://github.com/ADD-SP/ngx_waf/pull/4）。</a></li></ul><h3 id="改动-4" tabindex="-1">改动 <a class="header-anchor" href="#改动-4" aria-label="Permalink to &quot;改动&quot;">​</a></h3><ul><li>配置指令合并 (<a href="https://github.com/ADD-SP/ngx_waf/commit/ba92cfd53ce78da8ff4ed22d2bc71a47de4cbe25" target="_blank" rel="noreferrer">ba92cfd</a>)。这些配置指令将被合并：<code>waf_check_ipv4</code>，<code>waf_check_url</code>，<code>waf_check_args</code>，<code>waf_check_ua</code>，<code>waf_check_referer</code>，<code>waf_check_cookie</code>，<code>waf_check_post</code>，<code>waf_check_cookie</code>，<code>waf_cc_deny</code>。合并后的新指令为<code>waf_mode</code>，详情见<a href="https://github.com/ADD-SP/ngx_waf/blob/master/README-ZH.md" target="_blank" rel="noreferrer">README</a>。</li></ul><h3 id="修复-4" tabindex="-1">修复 <a class="header-anchor" href="#修复-4" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>删除一个默认的 User-Agent 规则，规则内容为<code>(?i)(?:Sogou web spider)</code>，原因是会拦截非恶意的网络爬虫（<a href="https://github.com/ADD-SP/ngx_waf/commit/827d4e5bc48894ff9147e49799d3a9656fe7dd8a" target="_blank" rel="noreferrer">827d4e5</a>）。</li><li>现在可以正确处理规则文件中的空行了（<a href="https://github.com/ADD-SP/ngx_waf/commit/955cf2d240c4d66f815890e3ee9b88ccf906cf1d" target="_blank" rel="noreferrer">955cf2d</a>）。</li></ul><hr><h2 id="_1-0-1-2020-08-22" tabindex="-1">[1.0.1] - 2020-08-22 <a class="header-anchor" href="#_1-0-1-2020-08-22" aria-label="Permalink to &quot;[1.0.1] - 2020-08-22&quot;">​</a></h2><h3 id="新增-5" tabindex="-1">新增 <a class="header-anchor" href="#新增-5" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>增加了新的配置项（<a href="https://github.com/ADD-SP/ngx_waf/commit/3214fc88d565ed47daa4bdac4f0edb7d1785ed75" target="_blank" rel="noreferrer">3214fc8</a>） <ul><li>waf_check_ipv4: <ul><li>配置语法: <code>waf_check_ipv4 [ on | off ];</code></li><li>默认值：<code>on</code></li><li>配置段: server</li><li>作用：是否启用 IPV4 检查。</li></ul></li><li>waf_check_url: <ul><li>配置语法: <code>waf_check_url [ on | off ];</code></li><li>默认值：<code>on</code></li><li>配置段: server</li><li>作用：是否启用 URL 检查。</li></ul></li><li>waf_check_args: <ul><li>配置语法: <code>waf_check_args [ on | off ];</code></li><li>默认值：<code>on</code></li><li>配置段: server</li><li>作用：是否启用 Args 检查。</li></ul></li><li>waf_check_ua: <ul><li>配置语法: <code>waf_check_ua [ on | off ];</code></li><li>默认值：<code>on</code></li><li>配置段: server</li><li>作用：是否启用 User-Agent 检查。</li></ul></li><li>waf_check_referer: <ul><li>配置语法: <code>waf_check_referer [ on | off ];</code></li><li>默认值：<code>on</code></li><li>配置段: server</li><li>作用：是否启用 Referer 检查。</li></ul></li><li>waf_check_cookie: <ul><li>配置语法: <code>waf_check_cookie [ on | off ];</code></li><li>默认值：<code>on</code></li><li>配置段: server</li><li>作用：是否启用 Cookie 检查。</li></ul></li><li>waf_check_post: <ul><li>配置语法: <code>waf_check_post [ on | off ];</code></li><li>默认值：<code>off</code></li><li>配置段: server</li><li>作用：是否启用 POST 检查。</li></ul></li><li>waf_cc_deny: <ul><li>配置语法: <code>waf_cc_deny [ on | off ];</code></li><li>默认值：<code>off</code></li><li>配置段: server</li><li>作用：是否启用 CC 防御。</li></ul></li></ul></li></ul><h3 id="改动-5" tabindex="-1">改动 <a class="header-anchor" href="#改动-5" aria-label="Permalink to &quot;改动&quot;">​</a></h3><ul><li><code>waf_mult_mount</code>现在只允许写在<code>server</code>段中（<a href="https://github.com/ADD-SP/ngx_waf/commit/3214fc88d565ed47daa4bdac4f0edb7d1785ed75" target="_blank" rel="noreferrer">3214fc8</a>）。 <ul><li>waf_mult_mount: <ul><li>配置语法: <code>waf_mult_mount [ on | off ];</code></li><li>默认值：<code>off</code></li><li>配置段: server</li><li>作用：进行多阶段检查，当<code>nginx.conf</code>存在地址重写的情况下（如<code>rewrite</code>配置）建议启用，反之建议关闭。</li></ul></li></ul></li><li>更改现有的配置项关键字，删除了<code>ngx_</code>前缀（<a href="https://github.com/ADD-SP/ngx_waf/commit/8b3e416cdfdc7e073a3392fc9ec027a4138af453" target="_blank" rel="noreferrer">8b3e416</a>）。 <ul><li>waf: <ul><li>配置语法: <code>waf [ on | off ];</code></li><li>默认值：<code>off</code></li><li>配置段: server</li><li>作用：是否启用本模块。</li></ul></li><li>waf_rule_path: <ul><li>配置语法: <code>waf_rule_path dir;</code></li><li>默认值：无</li><li>配置段: server</li><li>作用：规则文件所在目录，且必须以<code>/</code>结尾。</li></ul></li><li>waf_mult_mount: <ul><li>配置语法: <code>waf_mult_mount [ on | off ];</code></li><li>默认值：<code>off</code></li><li>配置段: http</li><li>作用：进行多阶段检查，当<code>nginx.conf</code>存在地址重写的情况下（如<code>rewrite</code>配置）建议启用，反之建议关闭。</li></ul></li></ul></li><li>更新 referer 的默认规则，具体一点就是拷贝<code>rules/url</code>的内容到<code>rules/referer</code>中（<a href="https://github.com/ADD-SP/ngx_waf/commit/55f5e26b6135af382b1db88057f5143631848ae7" target="_blank" rel="noreferrer">55f5e26</a>）。</li></ul><h3 id="修复-5" tabindex="-1">修复 <a class="header-anchor" href="#修复-5" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复 CC 防御功能检测逻辑的错误，该错误会导致实际的频率限制要远小于用户指定的限制，容易将正常访问识别为 CC 攻击（<a href="https://github.com/ADD-SP/ngx_waf/commit/9cb51bba0cdf10c2fd1ac0a482d7435dcfdee93d" target="_blank" rel="noreferrer">9cb51bb</a>）（<a href="https://github.com/ADD-SP/ngx_waf/commit/171721cee861022e9f3db5fceeb16051b90a5e54" target="_blank" rel="noreferrer">171721c</a>）。</li><li>现在会检查 rules/ipv4 和 rules/white-ipv4 这两个文件中的 IPV4 地址或地址块是否合法（<a href="https://github.com/ADD-SP/ngx_waf/commit/fc09f045d1e9ac774a919181a15c20a6c777a276" target="_blank" rel="noreferrer">fc09f04</a>）（<a href="https://github.com/ADD-SP/ngx_waf/commit/2e7f624581d8d85a23d6470acced9acc3e2840b2" target="_blank" rel="noreferrer">2e7f624</a>）。</li></ul><hr><h2 id="_1-0-0-2020-08-18" tabindex="-1">[1.0.0] - 2020-08-18 <a class="header-anchor" href="#_1-0-0-2020-08-18" aria-label="Permalink to &quot;[1.0.0] - 2020-08-18&quot;">​</a></h2><h3 id="新增-6" tabindex="-1">新增 <a class="header-anchor" href="#新增-6" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>改进日志格式（<a href="https://github.com/ADD-SP/ngx_waf/commit/bd112ecacd9356ee1e0731634cfc197034d25c88" target="_blank" rel="noreferrer">bd112ec</a>）。基本格式为<code>xxxxx, ngx_waf: [拦截类型][对应规则], xxxxx</code>，具体可看下面的例子。<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2020/01/20 22:56:30 [alert] 24289#0: *30 ngx_waf: [BLACK-URL][(?i)(?:/\\.env$)], client: 192.168.1.1, server: example.com, request: &quot;GET /v1/.env HTTP/1.1&quot;, host: &quot;example.com&quot;, referrer: &quot;http:/example.com/v1/.env&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2020/01/20 22:58:40 [alert] 24678#0: *11 ngx_waf: [BLACK-POST][(?i)(?:select.*(?:from|limit))], client: 192.168.1.1, server: example.com, request: &quot;POST /xmlrpc.php HTTP/1.1&quot;, host: &quot;example.com&quot;, referrer: &quot;https://example.com/&quot;</span></span></code></pre></div></li><li>新增三个内置变量（<a href="https://github.com/ADD-SP/ngx_waf/commit/92d6d847840ada57bbc54ffe2c0980b118a37a30" target="_blank" rel="noreferrer">92d6d84</a>） <ul><li><code>$waf_blocked</code>: 本次请求是否被本模块拦截，如果拦截了则其的值为<code>&#39;true&#39;</code>,反之则为<code>&#39;false&#39;</code>。</li><li><code>$waf_rule_type</code>：如果本次请求被本模块拦截，则其值为触发的规则类型。下面是可能的取值。若没有生效则其值为<code>&#39;null&#39;</code>。 <ul><li><code>&#39;BLACK-IPV4&#39;</code></li><li><code>&#39;BLACK-URL&#39;</code></li><li><code>&#39;BLACK-ARGS&#39;</code></li><li><code>&#39;BLACK-USER-AGENT&#39;</code></li><li><code>&#39;BLACK-REFERER&#39;</code></li><li><code>&#39;BLACK-COOKIE&#39;</code></li><li><code>&#39;BLACK-POST&#39;</code></li></ul></li><li><code>&#39;$waf_rule_details&#39;</code>：如果本次请求被本模块拦截，则其值为触发的具体的规则的内容。若没有生效则其值为<code>&#39;null&#39;</code>。</li></ul></li><li>支持过滤 POST 请求（<a href="https://github.com/ADD-SP/ngx_waf/commit/b46641eb8473c6dcb6afe9ed73f94712300d176f" target="_blank" rel="noreferrer">b46641e</a>）。</li><li>新配置项<code>ngx_waf_mult_mount</code>用于增加拦截面（<a href="https://github.com/ADD-SP/ngx_waf/commit/e1b500de349e017b67f334878342bdd6a34d22b8" target="_blank" rel="noreferrer">e1b500d</a>），典型的应用场景是存在<code>rewrite</code>的情况下重写前后均会对 URL 进行一次检测。</li><li>支持 CC 防御功能（<a href="https://github.com/ADD-SP/ngx_waf/commit/3a93e190b8cb78fcd7a0197f76298c010169d113" target="_blank" rel="noreferrer">3a93e19</a>）。</li></ul><h3 id="改动-6" tabindex="-1">改动 <a class="header-anchor" href="#改动-6" aria-label="Permalink to &quot;改动&quot;">​</a></h3><ul><li>增加默认的 POST 过滤规则（<a href="https://github.com/ADD-SP/ngx_waf/commit/68dd102e011acfd819669d60a35d315365d26a16" target="_blank" rel="noreferrer">68dd102</a>）</li><li>更新默认规则（<a href="https://github.com/ADD-SP/ngx_waf/commit/55f0a4824bafb67f562909bdb58292cfce1059ae" target="_blank" rel="noreferrer">55f0a48</a>）。</li><li>修改规则优先级（<a href="https://github.com/ADD-SP/ngx_waf/commit/3c388c85e30528b66306ca780524c7d663277f07" target="_blank" rel="noreferrer">3c388c8</a>）（<a href="https://github.com/ADD-SP/ngx_waf/commit/248958d3a0ef27dd14acc63a503e97931841f18a" target="_blank" rel="noreferrer">248958d</a>）（<a href="https://github.com/ADD-SP/ngx_waf/commit/b46641eb8473c6dcb6afe9ed73f94712300d176f" target="_blank" rel="noreferrer">b46641e</a>）（(92447a3)[<a href="https://github.com/ADD-SP/ngx_waf/commit/92447a39d6a36ab027b0ead0daa0fe2b3b74ff29" target="_blank" rel="noreferrer">https://github.com/ADD-SP/ngx_waf/commit/92447a39d6a36ab027b0ead0daa0fe2b3b74ff29</a>]），现在的优先级为（靠上的优先生效）： <ol><li>IP 白名单</li><li>IP 黑名单</li><li>CC 防御</li><li>URL 白名单</li><li>URL 黑名单</li><li>Args 黑名单</li><li>UserAgent 黑名单</li><li>Referer 白名单</li><li>Referer 黑名单</li><li>Cookie 黑名单</li><li>POST 黑名单</li></ol></li></ul><h3 id="修复-6" tabindex="-1">修复 <a class="header-anchor" href="#修复-6" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>IPV4 黑白名单功能失效（<a href="https://github.com/ADD-SP/ngx_waf/commit/231f94aa5383fe8f6cdc0fbc3cd2dcadb7606881" target="_blank" rel="noreferrer">231f94a</a>）。</li><li>当 User-agent 为空时会触发 segmentation fault（<a href="https://github.com/ADD-SP/ngx_waf/commit/bf33b366232b7f5e05379d5e10ab006696189ea6" target="_blank" rel="noreferrer">bf33b36</a>）。</li><li>启用 CC 防御后会有内存泄漏（<a href="https://github.com/ADD-SP/ngx_waf/commit/be58d189b4c95be066623604124b02a9bf174e7f" target="_blank" rel="noreferrer">be58d18</a>）。</li></ul>`,50)])])}const s=a(i,[["render",t]]);export{u as __pageData,s as default};
